import * as THREE from 'three';
import {GLTFLoader} from './vendor/GLTFLoader.js';
const $=s=>document.querySelector(s),manifest=await fetch('./assets/full-prototype-v012.json').then(r=>r.json());
const style=document.createElement('style');style.textContent=`#episodeFilm{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:1;opacity:0;transition:opacity 1.6s;pointer-events:none}.episode-panel{z-index:4!important;background:linear-gradient(90deg,#090d08e8,#090d08b0)!important;max-height:65vh}body[data-episode-phase=scan] #episodeFilm{opacity:0!important}#endingComposite{position:absolute;inset:0;z-index:2;pointer-events:none}#endingComposite canvas{width:100%;height:100%}.ending-black{position:absolute;inset:0;background:black;opacity:0;z-index:3;pointer-events:none;transition:none}#endingCaption{position:absolute;left:5vw;bottom:12vh;z-index:4;font:14px 'Gowun Batang';color:#e9e7dc;text-shadow:0 2px 8px black;letter-spacing:.15em}#endingFilm{object-fit:cover!important}body[data-episode='1'] .episode-panel,body[data-episode='4'] .episode-panel{left:5vw;right:auto!important}#episodeFilm:not([src]){display:none}#stageCue{background:#08100bad;padding:8px 14px;border-radius:20px}@media(max-width:650px){.episode-panel{top:auto!important;bottom:12vh;max-height:38vh;width:84vw}#episodeFilm{object-position:35% center}}`;document.head.append(style);
const episodeFilm=document.createElement('video');episodeFilm.id='episodeFilm';episodeFilm.muted=true;episodeFilm.playsInline=true;episodeFilm.preload='auto';$('#village').append(episodeFilm);
let selected=-1,episodeTarget=0,active=false;
document.addEventListener('prototype-episode',e=>{active=e.detail.active;episodeFilm.style.opacity=active?'1':'0';if(!active){episodeFilm.pause();return;}const i=e.detail.index;if(i!==selected){selected=i;episodeFilm.src=manifest.scenes[i].url;episodeFilm.load();}episodeTarget=Math.min(1,e.detail.progress/2.5);});
function episodeFrame(){requestAnimationFrame(episodeFrame);if(active&&episodeFilm.readyState>=2&&!episodeFilm.seeking){const desired=Math.min(episodeFilm.duration-.07,episodeTarget*episodeFilm.duration);const next=episodeFilm.currentTime+(desired-episodeFilm.currentTime)*.07;if(Math.abs(desired-episodeFilm.currentTime)>.05)episodeFilm.currentTime=next;}}episodeFrame();
const film=$('#endingFilm');const previousFrame=document.createElement('canvas');previousFrame.style.cssText='position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none';$('#memory').prepend(previousFrame);film.style.transition='opacity 1.5s';film.addEventListener('loadeddata',()=>film.style.opacity='1');film.removeAttribute('src');film.load();film.preload='auto';film.muted=true;
const black=document.createElement('div');black.className='ending-black';$('#memory').append(black);const caption=document.createElement('div');caption.id='endingCaption';$('#memory').append(caption);
const composite=document.createElement('div');composite.id='endingComposite';$('#memory').append(composite);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(-3.2,3.2,1.8,-1.8,.1,50),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.toneMapping=THREE.ACESFilmicToneMapping;composite.append(renderer.domElement);camera.position.set(0,1.6,8);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xfff6e7,0x4c625b,2));const key=new THREE.DirectionalLight(0xffe6c7,2.6);key.position.set(-3,6,4);scene.add(key);
const loader=new GLTFLoader();await Promise.all(['stone-lion.glb','stone-lion-female.glb'].map(async(name,i)=>{const g=await loader.loadAsync('./assets/'+name),model=g.scene,box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3());model.position.sub(box.getCenter(new THREE.Vector3()));const pivot=new THREE.Group();pivot.add(model);pivot.scale.setScalar(1.1/size.y);pivot.rotation.y=-Math.PI/4;pivot.position.set(i===0?.65:-.65,-.65,0);scene.add(pivot);}));
// Snow sits on a separate group, never on the scan geometry or material.
const snow=new THREE.Group();const snowMaterial=new THREE.MeshStandardMaterial({color:0xf2f4ed,roughness:1});scene.updateMatrixWorld(true);const snowRay=new THREE.Raycaster();for(const x of [-.65,.65]){for(const offset of [-.12,.1,.3]){snowRay.set(new THREE.Vector3(x+offset,3,0),new THREE.Vector3(0,-1,0));const hit=snowRay.intersectObjects(scene.children,true).find(h=>h.object.isMesh);if(!hit)continue;const cap=new THREE.Mesh(new THREE.SphereGeometry(1,24,12),snowMaterial);cap.scale.set(.13,.012,.10);cap.position.copy(hit.point);cap.position.y+=.005;snow.add(cap);}}scene.add(snow);snow.visible=false;
// Display-only ink treatment. Scan geometry, UVs and texture data stay unchanged.
const target=new THREE.WebGLRenderTarget(1,1,{format:THREE.RGBAFormat}),washScene=new THREE.Scene(),washCamera=new THREE.OrthographicCamera(-1,1,1,-1,0,1);
const washMaterial=new THREE.ShaderMaterial({transparent:true,depthTest:false,depthWrite:false,uniforms:{image:{value:target.texture},texel:{value:new THREE.Vector2(1,1)},amount:{value:0}},vertexShader:`varying vec2 uvv;void main(){uvv=uv;gl_Position=vec4(position.xy,0.,1.);}`,fragmentShader:`uniform sampler2D image;uniform vec2 texel;uniform float amount;varying vec2 uvv;float lum(vec3 c){return dot(c,vec3(.299,.587,.114));}void main(){vec4 c=texture2D(image,uvv);float l=sqrt(max(0.,lum(c.rgb)));float dx=lum(texture2D(image,uvv+vec2(texel.x*1.2,0.)).rgb)-lum(texture2D(image,uvv-vec2(texel.x*1.2,0.)).rgb);float dy=lum(texture2D(image,uvv+vec2(0.,texel.y*1.2)).rgb)-lum(texture2D(image,uvv-vec2(0.,texel.y*1.2)).rgb);float edge=smoothstep(.04,.18,length(vec2(dx,dy)));float tone=mix(l,floor(l*5.)/5.,.32);vec3 ink=vec3(.25,.32,.28),paper=vec3(.86,.87,.80);vec3 wash=mix(ink,paper,smoothstep(.06,.85,tone));wash=mix(wash,ink,edge*.38);float grain=fract(sin(dot(gl_FragCoord.xy,vec2(12.9898,78.233)))*43758.5453);wash+=(grain-.5)*.025;gl_FragColor=vec4(mix(c.rgb,wash,amount),c.a);}`});washScene.add(new THREE.Mesh(new THREE.PlaneGeometry(2,2),washMaterial));let inkStart=0;
function render(){const aspect=composite.clientWidth/composite.clientHeight;camera.left=-1.8*aspect;camera.right=1.8*aspect;camera.updateProjectionMatrix();renderer.setSize(composite.clientWidth,composite.clientHeight,false);const size=renderer.getDrawingBufferSize(new THREE.Vector2());target.setSize(size.x,size.y);washMaterial.uniforms.texel.value.set(1/size.x,1/size.y);renderer.setRenderTarget(target);renderer.setClearColor(0x000000,0);renderer.clear();renderer.render(scene,camera);renderer.setRenderTarget(null);renderer.clear();renderer.render(washScene,washCamera);}new ResizeObserver(render).observe(composite);
const seasons=manifest.scenes.slice(5),labels=['고려 · 봄','고려 · 여름','고려 · 가을','고려 · 겨울','조선 · 봄','조선 · 여름','조선 · 가을','조선 · 겨울','현재 · 여름'];let shot=-1,ending=false,hold=0;
function setShot(i){if(film.readyState>=2){previousFrame.width=film.videoWidth;previousFrame.height=film.videoHeight;previousFrame.getContext('2d').drawImage(film,0,0);}film.style.opacity='0';shot=i;film.src=seasons[i].url;film.load();caption.textContent=labels[i];snow.visible=i===3||i===7;key.color.set(i===3||i===7?0xdce8ff:i===2||i===6?0xffce92:0xffe6c7);render();film.play().catch(()=>{caption.textContent=labels[i]+' · 재생을 눌러주세요';});}
function start(){inkStart=performance.now();washMaterial.uniforms.amount.value=0;caption.style.opacity=1;ending=true;hold=0;black.style.opacity=0;composite.style.opacity=1;setShot(0);$('#endingPlay').textContent='다시 재생';}
document.addEventListener('prototype-ending',start);film.addEventListener('ended',()=>{if(!ending)return;if(shot<8)setShot(shot+1);else hold=performance.now();});
function tick(now){requestAnimationFrame(tick);if(!ending)return;washMaterial.uniforms.amount.value=Math.min(1,(now-inkStart)/6500);render();if(document.body.dataset.stage!=='memory'){ending=false;film.pause();return;}if(hold){const t=(now-hold)/1000,fade=Math.max(0,Math.min(1,(t-12)/7));black.style.opacity=fade;caption.style.opacity=1-fade;if(t>=19){ending=false;$('#restartStory').focus({preventScroll:true});}}}requestAnimationFrame(tick);
document.addEventListener('story-home',()=>{ending=false;film.pause();black.style.opacity=0;caption.style.opacity=1;});
document.addEventListener('stage-navigate',e=>{if(e.detail==='memory'&&!ending)setTimeout(()=>{if(!ending)start();},300);});
document.addEventListener('experience-selected',()=>{if(location.hash==='#memory')setTimeout(()=>{if(!ending)start();},500);});
